"""Public cascade operations UI. Tokens and SSH keys are never rendered."""
import json
from wpp_cascade import ENTRY_PROTOCOLS
import wpp_cascade_ops as ops
import wpp_ssh_cascade as ssh


def render(connections,nodes,domain,path,csrf):
    try:state=ssh.load('/etc/web-proxy-panel/ssh-cascades.json')
    except ssh.SSHError:state={'servers':{},'routes':{}}
    rows=[]
    for row in connections:
        if row.get('protocol') not in ENTRY_PROTOCOLS:continue
        route=state['routes'].get(row['id'],{})
        hops=ssh.Controller.hops(route) if route else []
        rows.append({'id':row['id'],'name':row['name'],'enabled':bool(row.get('enabled',True)),
                     'kind':ops.route_kind(row),'plan':row.get('config',{}).get('cascade',{}),
                     'entry':hops[0]['server_id'] if hops else '',
                     'middle':hops[1]['server_id'] if len(hops)>1 else '',
                     'middle_port':hops[1]['config']['listen_port'] if len(hops)>1 else 443})
    public_servers=[{'id':nid,'host':node['host']} for nid,node in state['servers'].items()]
    public_nodes=[{'id':n['id'],'name':n.get('name') or n.get('country_name') or n['url'],
                   'country_code':n.get('country_code','')} for n in nodes if n.get('enabled',True)]
    # Never embed node URL auth components; use the existing sanitized host view.
    from urllib.parse import urlsplit
    for node in public_nodes:
        if '://' in node['name']:node['name']=urlsplit(node['name']).hostname or 'Сервер'
    data=json.dumps({'connections':rows,'servers':public_servers,'nodes':public_nodes,'domain':domain,'path':path,'csrf':csrf},ensure_ascii=False).replace('<','\\u003c')
    return MARKUP.replace('__OPS_DATA__',data)


